 14	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
 15	 * (half-even) at every step.
 16	 */
 17	public final class PriceCalculator {
 18	
 19	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
 20	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
 21	    static final BigDecimal LONG_STAY_DISCOUNT = new BigDecimal("0.10");
 22	
 23	    private static final Map<String, BigDecimal> CORPORATE_DISCOUNTS = Map.of(
 24	            "TECNOSUL", new BigDecimal("0.12"),
 25	            "AGROVALE", new BigDecimal("0.18"),
 26	            "FARMAVIDA", new BigDecimal("0.25")
 27	    );
 28	
 29	    private static final Map<RoomType, BigDecimal> WEEKEND_PACKAGE_PRICES = Map.of(
 30	            RoomType.STANDARD, new BigDecimal("520.00"),
 31	            RoomType.DELUXE, new BigDecimal("820.00"),
 32	            RoomType.SUITE, new BigDecimal("1200.00")
 33	    );
 34	
 35	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
 36	        int nights = countNights(checkIn, checkOut);
 37	
 38	        return switch (ratePlan) {
 39	            case STANDARD -> calculateStandard(room, checkIn, checkOut, nights);
 40	            case NON_REFUNDABLE -> calculateNonRefundable(room, checkIn, checkOut, nights);
 41	            case CORPORATE -> calculateCorporate(room, checkIn, checkOut, nights, companyCode);
 42	            case WEEKEND_PACKAGE -> calculateWeekendPackage(room, checkIn, checkOut, nights);
 43	            case LONG_STAY -> calculateLongStay(room, checkIn, checkOut, nights);
 44	        };
 45	    }
 46	
 47	    private Price calculateStandard(Room room, LocalDate checkIn, LocalDate checkOut, int nights) {
 48	        BigDecimal subtotal = calculateSubtotal(room, checkIn, checkOut);
 49	        BigDecimal discount = cents(BigDecimal.ZERO);
 50	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
 51	    }
 52	
 53	    private Price calculateNonRefundable(Room room, LocalDate checkIn, LocalDate checkOut, int nights) {
 54	        BigDecimal subtotal = calculateSubtotal(room, checkIn, checkOut);
 55	        BigDecimal discount = cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
 56	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
 57	    }
 58	
 59	    private Price calculateCorporate(Room room, LocalDate checkIn, LocalDate checkOut, int nights, String companyCode) {
 60	        if (companyCode == null || !CORPORATE_DISCOUNTS.containsKey(companyCode)) {
 61	            throw new HotelException(ErrorCode.INVALID_REQUEST,
 62	                    "corporate rate plan requires a valid company code (TECNOSUL, AGROVALE, or FARMAVIDA)");
 63	        }
 64	        BigDecimal subtotal = calculateSubtotal(room, checkIn, checkOut);
 65	        BigDecimal discountRate = CORPORATE_DISCOUNTS.get(companyCode);
 66	        BigDecimal discount = cents(subtotal.multiply(discountRate));
 67	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
 68	    }
 69	
 70	    private Price calculateWeekendPackage(Room room, LocalDate checkIn, LocalDate checkOut, int nights) {
 71	        if (nights != 2) {
 72	            throw new HotelException(ErrorCode.INVALID_REQUEST,
 73	                    "weekend package requires exactly 2 nights");
 74	        }
 75	        if (checkIn.getDayOfWeek() != DayOfWeek.FRIDAY) {
 76	            throw new HotelException(ErrorCode.INVALID_REQUEST,
 77	                    "weekend package must start on Friday");
 78	        }
 79	        if (checkOut.getDayOfWeek() != DayOfWeek.SUNDAY) {
 80	            throw new HotelException(ErrorCode.INVALID_REQUEST,
 81	                    "weekend package must end on Sunday");
 82	        }
 83	        BigDecimal packagePrice = WEEKEND_PACKAGE_PRICES.get(room.type());
 84	        return new Price(nights, packagePrice, cents(BigDecimal.ZERO), packagePrice);
 85	    }
 86	
 87	    private Price calculateLongStay(Room room, LocalDate checkIn, LocalDate checkOut, int nights) {
 88	        if (nights < 7) {
 89	            throw new HotelException(ErrorCode.INVALID_REQUEST,
 90	                    "long stay rate plan requires at least 7 nights");
 91	        }
 92	        BigDecimal subtotal = calculateSubtotal(room, checkIn, checkOut);
 93	        BigDecimal discount = cents(subtotal.multiply(LONG_STAY_DISCOUNT));
 94	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
 95	    }
 96	
 97	    private BigDecimal calculateSubtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
 98	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 99	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
100	            subtotal = subtotal.add(nightPrice(room, night));
101	        }
102	        return subtotal;
103	    }
104	
105	    private int countNights(LocalDate checkIn, LocalDate checkOut) {
106	        int nights = 0;
107	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
108	            nights++;
109	        }
110	        return nights;
111	    }
112	
113	    BigDecimal nightPrice(Room room, LocalDate night) {
114	        BigDecimal nightlyRate = room.nightlyRate();
115	        if (isHighSeason(night)) {
116	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
117	        }
118	        return cents(nightlyRate);
119	    }
120	
121	    /** High season: from December 15 to the end of February, and the whole of July. */
122	    static boolean isHighSeason(LocalDate date) {
123	        Month month = date.getMonth();
124	        return month == Month.JANUARY
125	                || month == Month.FEBRUARY
126	                || month == Month.JULY
127	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
128	    }
129	
130	    static BigDecimal cents(BigDecimal value) {
131	        return value.setScale(2, RoundingMode.HALF_EVEN);
132	    }
